<script setup lang="ts">
const list = ref<any[]>([]), settings = ref<any>(null), loading = ref(true), error = ref(''), status = ref(''), q = ref(''), compose = ref(false), detail = ref<any>(null), busy = ref(false)
const statusLabels: Record<string, string> = { accepted: 'Diterima MPWA', failed: 'Ditolak', unknown: 'Belum pasti', sending: 'Diproses' }
const modeLabels: Record<string, string> = { text: 'Teks', link: 'Tautan dokumen', pdf: 'Lampiran PDF' }
const filtered = computed(() => list.value.filter(m => (!status.value || status.value === m.status) && `${m.reference} ${m.recipient}`.toLowerCase().includes(q.value.toLowerCase())))
const pages = usePagination(filtered, { resetOn: [status, q] })
async function load() { loading.value = true; error.value = ''; try { [list.value, settings.value] = await Promise.all([api('/api/whatsapp/history'), api('/api/whatsapp/settings')]) } catch (e) { error.value = errMsg(e) } finally { loading.value = false } }
onMounted(load)
async function revoke() { if (!detail.value || busy.value) return; busy.value = true; try { await api(`/api/whatsapp/history/${detail.value.id}/revoke`, { method: 'POST' }); detail.value.revoked = true; toast('Tautan ditutup. Pesan WhatsApp yang sudah diterima tidak dihapus.'); await load() } catch (e) { toast(errMsg(e), 'error') } finally { busy.value = false } }
</script>
<template>
  <div class="card op-hero"><div><h2>Pengiriman WhatsApp</h2><p>Invoice pelanggan, dokumen mitra, dan pesan operasional melalui MPWA.</p></div><div class="op-actions"><NuxtLink to="/pengaturan#mpwa" class="btn btn-sec">Pengaturan MPWA</NuxtLink><button class="btn btn-primary" @click="compose = true"><Ico name="plus" :size="16" /> Pesan baru</button></div></div>
  <div v-if="settings && !settings.enabled" class="op-note">Gateway belum aktif. Lengkapi pengaturan MPWA untuk mulai mengirim. Invoice dapat dikirim dari preview di Keuangan; PKS/FAB dari Dokumen.</div>
  <div v-else-if="settings" class="op-note"><strong>Sender {{ settings.sender }}</strong>Pengiriman diaktifkan. Status koneksi perangkat dapat diperiksa di dashboard MPWA.</div>
  <div class="op-filters"><input v-model="q" class="ctrl" aria-label="Cari pengiriman" placeholder="Cari nomor dokumen atau penerima"><select v-model="status" class="ctrl" aria-label="Filter status pengiriman"><option value="">Semua status</option><option v-for="(label, key) in statusLabels" :key="key" :value="key">{{ label }}</option></select><button class="btn btn-sec" :disabled="loading" @click="load">Muat ulang</button></div>
  <div v-if="loading" class="empty">Memuat riwayat…</div><p v-else-if="error" class="op-note op-warning" role="alert">{{ error }}</p><section v-else class="card"><div class="table-wrap"><table class="tbl"><thead><tr><th>Waktu</th><th>Dokumen / pesan</th><th>Penerima</th><th>Isi</th><th>Status</th><th>Detail</th></tr></thead><tbody><tr v-for="m in pages.rows" :key="m.id"><td>{{ new Date(m.created_at).toLocaleString('id-ID') }}</td><td class="cell-main">{{ m.reference }}</td><td>{{ m.recipient }}</td><td>{{ modeLabels[m.mode] }}</td><td><span class="op-status" :class="{ off: m.status !== 'accepted' }">{{ statusLabels[m.status] }}</span></td><td><button class="btn btn-sec btn-sm" @click="detail = m">Lihat</button></td></tr><tr v-if="!pages.total"><td colspan="6" class="empty">{{ list.length ? 'Tidak ada pengiriman yang cocok.' : 'Belum ada pengiriman. Kirim invoice dari preview atau pilih Pesan baru.' }}</td></tr></tbody></table></div><TablePagination v-model:page="pages.page" v-model:page-size="pages.pageSize" :total="pages.total" label="pengiriman WhatsApp" /></section>
  <p class="op-text">“Diterima MPWA” berarti gateway menerima permintaan, belum memastikan pesan sampai atau dibaca. Jika hasil belum pasti, periksa riwayat MPWA sebelum mengirim ulang.</p>
  <WhatsAppComposer :open="compose" kind="custom" @close="compose = false" @sent="load" />
  <UiModal :open="!!detail" title="Rincian pengiriman" :busy="busy" @close="detail = null"><template v-if="detail"><div class="op-kv"><span>Dokumen</span><b>{{ detail.reference }}</b></div><div class="op-kv"><span>Penerima</span><b>{{ detail.recipient }}</b></div><div class="op-kv"><span>Status</span><b>{{ statusLabels[detail.status] }}</b></div><p v-if="detail.error" class="op-note op-warning">{{ detail.error }}</p><p v-if="detail.provider_id" class="cell-sub">ID MPWA: {{ detail.provider_id }}</p><pre class="wa-sent-message">{{ detail.message }}</pre><template v-if="detail.has_share"><p class="op-text">{{ detail.revoked ? 'Tautan sudah ditutup.' : 'Tautan HTML berlaku 7 hari; pengambilan PDF 24 jam. Menutup tautan tidak menarik pesan atau file yang telah diunduh.' }}</p><button class="btn btn-sec" :disabled="detail.revoked || busy" @click="revoke">Tutup akses tautan / lampiran</button></template></template></UiModal>
</template>
<style scoped>.wa-sent-message{font:13px/1.8 Arial;white-space:pre-wrap;overflow-wrap:anywhere;padding:18px;border-radius:8px;background:#f4f7fb;margin:20px 0}.op-filters>.ctrl{width:auto;min-width:190px}@media(max-width:700px){.op-filters>.ctrl{width:100%}}</style>
